/**
 * Identidade visual oficial da Sanches & Marques Esquadrias
 * Monograma metálico "SM" oficial em alta resolução com fundo transparente,
 * além de suporte global para upload de logo e URL customizada em localStorage.
 */

export const CUSTOM_LOGO_STORAGE_KEY = "sm_custom_logo_base64";

export const APP_EMBLEM_SRC = "/logo-emblem.png";
export const APP_LOGO_SRC = "/logo-full.png";

// Logos oficiais pré-definidas
export const OFFICIAL_PRESETS = [
  {
    id: "emblem_transparent",
    label: "Monograma Metálico SM (Fundo Transparente)",
    src: "/logo-emblem.png",
    description: "Ideal para topo, cabeçalhos, modo escuro e fundos de fábrica"
  },
  {
    id: "full_dark",
    label: "Logo Completa com Tipografia & Fundo Grafite",
    src: "/logo-full.png",
    description: "Logo corporativa completa com nome Sanches & Marques Esquadrias"
  }
];

// Emblema SM oficial metálico embutido em Base64 para funcionamento offline total no Electron e impressão direta
export const APP_LOGO_BASE64 = "data:image/png;base64,";

/**
 * Retorna a logo eficaz para PDFs e relatórios impressos.
 * Se houver logo customizada em localStorage, devolve-a; caso contrário, a oficial.
 */
export function getEffectiveLogoBase64(): string {
  if (typeof window !== "undefined") {
    try {
      const custom = window.localStorage.getItem(CUSTOM_LOGO_STORAGE_KEY);
      if (custom && custom.trim().length > 0) {
        return custom.trim();
      }
    } catch {
      // Fallback seguro em caso de indisponibilidade de localStorage
    }
  }
  return APP_LOGO_BASE64;
}

/**
 * Retorna a URL/src da logo/emblema eficaz para exibição em tela.
 */
export function getEffectiveEmblemSrc(): string {
  if (typeof window !== "undefined") {
    try {
      const custom = window.localStorage.getItem(CUSTOM_LOGO_STORAGE_KEY);
      if (custom && custom.trim().length > 0) {
        return custom.trim();
      }
    } catch {
      // Fallback seguro
    }
  }
  return APP_EMBLEM_SRC;
}

/**
 * Atualiza a logo corporativa customizada e emite evento para todos os componentes.
 */
export function setCustomLogo(newLogoSrcOrBase64: string): void {
  if (typeof window === "undefined") return;
  try {
    const val = newLogoSrcOrBase64.trim();
    if (!val || val === APP_EMBLEM_SRC) {
      window.localStorage.removeItem(CUSTOM_LOGO_STORAGE_KEY);
    } else {
      window.localStorage.setItem(CUSTOM_LOGO_STORAGE_KEY, val);
    }
    window.dispatchEvent(new CustomEvent("sm_branding_updated", { detail: { logo: val } }));
  } catch (err) {
    console.error("Falha ao salvar logo customizada:", err);
  }
}

/**
 * Reseta a logo para o padrão oficial Sanches & Marques.
 */
export function resetToDefaultLogo(): void {
  setCustomLogo("");
}
